window.IELTS_EXAM_NOTES={
 identify:{senses:[['识别；认出','identify a person','识别某个人'],['确定；找出','identify the cause','找出原因']],tip:'阅读中常替换 recognise、detect、establish，但 identify the cause 强调确定具体原因；不要把“发现存在”自动理解为“确认是什么”。',cluster:'识别与评估'},
 evaluate:{senses:[['评估价值、质量或效果','evaluate the effectiveness','评估有效性']],tip:'Task 2 可用 evaluate the impact of a policy；比 say whether it is good 更精确。',cluster:'识别与评估'},
 claim:{senses:[['声称；主张（未必已经证实）','claim that a policy works','声称某政策有效'],['要求；索赔','claim compensation','要求赔偿']],tip:'The author claims… 表示作者提出观点，不等于研究已证明；claim、argue、demonstrate 的证据强度不同。',cluster:'证据与论证'},
 evidence:{senses:[['证据；依据（通常不可数）','strong evidence for the claim','支持该主张的有力证据']],tip:'写作使用 evidence suggests that…，避免写 an evidence；需要计数时用 a piece of evidence。',cluster:'证据与论证'},
 feature:{senses:[['特点；特征（名词）','a distinctive feature','一个独特特点'],['以……为特色；包含（动词）','the design features a courtyard','这个设计包含一个庭院']],tip:'注意词性：the main feature is… 与 the building features… 的结构不同。',cluster:'特征与差异'},
 measure:{senses:[['测量；衡量（动词）','measure the impact','衡量影响'],['措施（名词）','take effective measures','采取有效措施']],tip:'研究题先分清 measured temperature 与 measures to reduce heat；一个是变量测量，一个是应对措施。',cluster:'研究方法'},
 attribute:{senses:[['把……归因于（动词 /əˈtrɪbjuːt/）','attribute the change to rainfall','将变化归因于降雨'],['属性；特征（名词 /ˈætrɪbjuːt/）','a key attribute of the design','设计的一项关键属性']],tip:'attribute A to B 表示把 A 归因于 B，方向不要反过来。',cluster:'证据与论证'},
 'attribute ... to':{senses:[['将结果归因于某原因','attribute the decline to pollution','把下降归因于污染']],tip:'A 是结果，B 是所提出的原因；作者归因不一定已经排除了所有其他解释。',cluster:'证据与论证'},
 particular:{senses:[['特定的；某一具体的','a particular group','一个特定群体'],['尤其；特别（固定短语）','in particular','尤其是']],tip:'a particular group 不能替换成 all groups；in particular 用来缩小话题范围。',cluster:'范围与限定'},
 immediate:{senses:[['立即的；直接的','an immediate response','立即作出回应'],['紧邻的；当前附近的','the immediate surroundings','周围紧邻的环境']],tip:'immediate effect 表示即时效果；immediate area 说的是空间范围。',cluster:'范围与限定'},
 underlying:{senses:[['根本的；潜在的','an underlying cause','根本原因']],tip:'区别 symptom 与 underlying cause；文章描述症状，不等于给出了根本原因。',cluster:'证据与论证'},
 potential:{senses:[['可能的；潜在的（形容词）','potential benefits','潜在收益'],['潜力（名词）','have the potential to improve health','具有改善健康的潜力']],tip:'potential benefit 不能改写为 a proven benefit；写作可以用 has the potential to… 表达有条件的可能性。',cluster:'可能性与能力'},
 variable:{senses:[['变量（名词）','control other variables','控制其他变量'],['可变的；不固定的（形容词）','variable results','变化不定的结果']],tip:'题中出现数字时，先标明它与哪个 variable、单位和时间对应。',cluster:'研究方法'},
 variation:{senses:[['差异；变化','demographic variation','人口特征差异']],tip:'variation between groups 与 variation over time 分别比较群体和时间，不能混淆。',cluster:'特征与差异'},
 retain:{senses:[['保留；保持','retain the original structure','保留原有结构'],['留住；记住','retain information','记住信息']],tip:'阅读 retain 常替换 keep 或 maintain，具体宾语决定含义。',cluster:'保留与恢复'},
 recover:{senses:[['恢复；康复','recover from an illness','从疾病中恢复'],['找回；恢复取得','recover lost data','恢复丢失的数据']],tip:'recover from a problem 与 recover something 的句型不同。',cluster:'保留与恢复'},
 alternative:{senses:[['替代方案（名词）','a viable alternative','可行的替代方案'],['替代的（形容词）','alternative transport','替代交通方式']],tip:'an alternative to driving 以 to 引出被替代的活动；可写 offer a practical alternative to… 。',cluster:'选择与政策'},
 intervention:{senses:[['干预；介入','a targeted intervention','有针对性的干预']],tip:'适合政策与健康题：a targeted intervention may address…；区分采取干预和已经证实有效。',cluster:'选择与政策'},
 exacerbate:{senses:[['使问题或负面状况恶化','exacerbate water shortages','加剧缺水']],tip:'通常接负面问题，如 inequality、pollution、shortages；不用于一般正面改善。',cluster:'恶化与加剧'},
 deteriorate:{senses:[['恶化；变坏（通常不及物）','conditions deteriorate','状况恶化']],tip:'exacerbate a problem 使问题加剧；the situation deteriorates 状况自身变坏。',cluster:'恶化与加剧'},
 resilience:{senses:[['恢复能力；韧性','urban resilience','城市韧性']],tip:'名词 resilience 与形容词 resilient 保留词族；写作 connect resilience with the ability to recover。',cluster:'保留与恢复'},
 resilient:{senses:[['能恢复的；有韧性的','a resilient community','有韧性的社区']],tip:'resilient 强调受到冲击后恢复；durable 强调经久耐用，不能一概互换。',cluster:'保留与恢复'}
};
